INSERT INTO _migration_300_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_music_b005_036' AND NOT (q.topic_id IS 'topic_was_music_b005_8' AND q.subject_id IS 'subj_wassce_music' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the purpose of a tuning reference before ensemble rehearsal?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Practise it slowly in small sections before restoring tempo","B. To capture a strong signal without clipping distortion","C. The ability to perform unfamiliar notation accurately at first encounter","D. To align performers to a common pitch standard"]' AND q.correct_answer IS 'D' AND q.explanation IS 'A shared reference reduces conflicting intonation and allows instruments and voices to blend consistently across the ensemble. Therefore the correct answer is D: To align performers to a common pitch standard.' AND q.difficulty IS 'hard' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_music_b005_8' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_music_b005_036' AND NOT (r.batch_id IS 'wassce-foundation-beta-005' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Music practice aligned to official Ghana curriculum and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
